/* gethostname for OS-9/68k. * * OS-9 has no hostname: there is no node name in the system globals and no * resolver to ask. Callers here -- uucico and uux -- only want something to * put in a log line and a lock file, so this answers "localhost" and returns * 0, which is what every one of them checks. * * Separate from os9getpw.c on purpose: a tree that links blarslib already has * getpwnam and getpwuid, and adding that shim as well makes l68 refuse the * link on a duplicate psect. */int gethostname(name, len)     char *name;     int len;{    char *node = "localhost";    register int i;    for (i = 0; i < len - 1 && node[i] != '\0'; i++)        name[i] = node[i];    name[i] = '\0';    return 0;}